record ProblemDetails(String type, String title, int status, String detail, String instance) {}

ProblemDetails notFound(String resourcePath, String detail) {
    return new ProblemDetails(
        "https://example.com/problems/not-found",
        "Zasob nie znaleziony",
        404,
        detail,
        resourcePath
    );
}

ProblemDetails badRequest(String detail, String instance) {
    return new ProblemDetails("https://example.com/problems/bad-request",
        "Nieprawidlowe zadanie", 400, detail, instance);
}

ProblemDetails internalError(String correlationId, String instance) {
    return new ProblemDetails("https://example.com/problems/internal-error",
        "Wystapil blad wewnetrzny", 500,
        "Sprobuj ponownie pozniej. ID incydentu: " + correlationId, instance);
}
